// Shape only. No decision is made here on legal grounds: the platform
// decides what matters.
//
// Gmail hands a message over in more than one shape depending on the node
// version and whether simplify is on, so the headers are read from either the
// simplified object or the raw payload array rather than assumed.

const MAX_BYTES = 15 * 1024 * 1024;

function headers(message) {
  if (message.headers && !Array.isArray(message.headers)) {
    return Object.fromEntries(
      Object.entries(message.headers).map(([key, value]) => [key.toLowerCase(), value]),
    );
  }
  const raw = message.payload?.headers ?? [];
  return Object.fromEntries(raw.map((one) => [String(one.name).toLowerCase(), one.value]));
}

function address(value) {
  if (!value) return '';
  const match = String(value).match(/<([^>]+)>/);
  return (match ? match[1] : String(value)).trim();
}

function people(value) {
  if (!value) return [];
  return String(value)
    .split(',')
    .map((one) => one.trim())
    .filter(Boolean)
    .map((one) => ({ name: one.replace(/<[^>]*>/, '').trim(), address: address(one) }));
}

const messages = $input.all().map((item) => {
  const message = item.json;
  const head = headers(message);

  // Attachments arrive as binary properties, base64 in `.data`. This is true
  // in the default binary mode; with N8N_DEFAULT_BINARY_DATA_MODE=filesystem
  // n8n stores them on disk and `.data` is absent, which is why anything
  // without it is skipped rather than sent as undefined.
  const attachments = Object.values(item.binary ?? {})
    .filter((one) => typeof one.data === 'string')
    .filter((one) => one.fileName)
    .filter((one) => Buffer.from(one.data, 'base64').length <= MAX_BYTES)
    .map((one) => ({
      filename: one.fileName,
      content_type: one.mimeType || 'application/octet-stream',
      content_base64: one.data,
    }));

  const received = message.internalDate
    ? new Date(Number(message.internalDate)).toISOString()
    : new Date(head.date ?? Date.now()).toISOString();

  return {
    external_id: message.id,
    mailbox: $env.EAI_LEGAL_MAILBOX,
    sender: address(head.from) || 'unknown',
    subject: head.subject ?? message.subject ?? '(no subject)',
    body: message.text ?? message.textPlain ?? message.html ?? message.snippet ?? '',
    received_at: received,
    participants: [...people(head.to), ...people(head.cc)],
    attachments,
  };
});

if (!messages.length) return [];
return [{ json: { messages } }];

// The signature is over the exact bytes that will be sent, which is why the
// body is serialised here and handed on as a string. Serialising it again in
// the HTTP node would produce a different body and a signature that does not
// verify.
const crypto = require('crypto');
const body = JSON.stringify($json);
const signature = crypto
  .createHmac('sha256', $env.DSNLAI_WEBHOOK_SECRET)
  .update(body)
  .digest('hex');
return [{ json: { body, signature } }];

// Only reached when the hand-off did not throw, so a message is marked read
// after the platform holds it and never before. A failed pass leaves
// everything unread and the next one picks it up again; the platform drops a
// repeat by external_id, so a double delivery costs nothing.
return $('Read the shared mailbox').all().map((item) => ({ json: { id: item.json.id } }));
